class Rectangle:
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h

    def perimeter(self):
        return 2 * (self.w + self.h)

w, h = map(int, input().split())
r = Rectangle(w, h)
print('面积:' + str(r.area()))
print('周长:' + str(r.perimeter()))

import math

class Circle:
    def __init__(self, r):
        self.r = r

    def area(self):
        return math.pi * self.r * self.r

    def circumference(self):
        return 2 * math.pi * self.r

r = float(input())
c = Circle(r)
print('面积:{:.2f}'.format(c.area()))
print('周长:{:.2f}'.format(c.circumference()))

class Counter:
    def __init__(self):
        self.value = 0

    def add(self, n):
        self.value += n

    def reset(self):
        self.value = 0

    def get(self):
        return self.value

m = int(input())
c = Counter()
for i in range(m):
    cmd = input().split()
    if cmd[0] == 'add':
        c.add(int(cmd[1]))
    else:
        c.reset()
    print(c.get())

class Student:
    def __init__(self, name, scores):
        self.name = name
        self.scores = scores

    def total(self):
        return sum(self.scores)

    def average(self):
        return self.total() / len(self.scores)

    def is_pass(self):
        return self.average() >= 60

name = input()
scores = list(map(int, input().split()))
s = Student(name, scores)
print(s.name, s.total(), '{:.1f}'.format(s.average()), '及格' if s.is_pass() else '不及格')

class Book:
    def __init__(self, title, stock):
        self.title = title
        self.stock = stock

    def borrow(self):
        if self.stock > 0:
            self.stock -= 1
            return True
        return False

    def give_back(self):
        self.stock += 1

title, stock = input().split()
b = Book(title, int(stock))
for op in input():
    if op == 'B':
        print('借出成功' if b.borrow() else '库存不足')
    elif op == 'R':
        b.give_back()
        print('已归还')
print('《' + b.title + '》剩余' + str(b.stock) + '本')

class Cart:
    def __init__(self):
        self.items = []

    def add(self, name, price, qty):
        self.items.append((name, price, qty))

    def count(self):
        k = 0
        for it in self.items:
            k += it[2]
        return k

    def total(self):
        s = 0
        for it in self.items:
            s += it[1] * it[2]
        return s

n = int(input())
cart = Cart()
for i in range(n):
    name, price, qty = input().split()
    cart.add(name, float(price), int(qty))
print('共{}件 合计{:.2f}元'.format(cart.count(), cart.total()))

class Thermometer:
    def __init__(self):
        self.data = []

    def record(self, t):
        self.data.append(t)

    def highest(self):
        return max(self.data)

    def lowest(self):
        return min(self.data)

    def average(self):
        return sum(self.data) / len(self.data)

th = Thermometer()
for t in map(int, input().split()):
    th.record(t)
print('最高{} 最低{} 平均{:.1f}'.format(th.highest(), th.lowest(), th.average()))

import math

class Fraction:
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def simplify(self):
        g = math.gcd(self.a, self.b)
        self.a = self.a // g
        self.b = self.b // g

    def show(self):
        if self.b == 1:
            return str(self.a)
        return str(self.a) + '/' + str(self.b)

a, b = map(int, input().split())
f = Fraction(a, b)
f.simplify()
print(f.show())

