class Vote:
    def __init__(self):
        self.count = {}

    def vote(self, name):
        self.count[name] = self.count.get(name, 0) + 1

    def result(self):
        return sorted(self.count.items(), key=lambda x: x[1], reverse=True)

    def winner(self):
        return self.result()[0][0]

v = Vote()
for name in input().split():
    v.vote(name)
for name, n in v.result():
    print(name + ':' + str(n))
print('当选:' + v.winner())

class Password:
    def __init__(self, pwd):
        self.pwd = pwd

    def score(self):
        k = 0
        if len(self.pwd) >= 8:
            k += 1
        if any(ch.isdigit() for ch in self.pwd):
            k += 1
        if any(ch.isupper() for ch in self.pwd):
            k += 1
        if any(ch.islower() for ch in self.pwd):
            k += 1
        return k

    def level(self):
        s = self.score()
        if s <= 2:
            return '弱'
        elif s == 3:
            return '中'
        return '强'

n = int(input())
for i in range(n):
    print(Password(input()).level())

class Course:
    def __init__(self):
        self.records = []

    def add(self, name, score):
        self.records.append((name, score))

    def average(self):
        return sum(r[1] for r in self.records) / len(self.records)

    def top(self, k):
        rs = sorted(self.records, key=lambda r: r[1], reverse=True)
        return [r[0] for r in rs[:k]]

n = int(input())
c = Course()
for i in range(n):
    name, score = input().split()
    c.add(name, int(score))
k = int(input())
print('平均分:{:.1f}'.format(c.average()))
print(' '.join(c.top(k)))

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return '...'

class Dog(Animal):
    def speak(self):
        return '汪汪'

class Cat(Animal):
    def speak(self):
        return '喵喵'

n = int(input())
for i in range(n):
    kind, name = input().split()
    if kind == 'dog':
        a = Dog(name)
    elif kind == 'cat':
        a = Cat(name)
    else:
        a = Animal(name)
    print(a.name + ':' + a.speak())

class Employee:
    def __init__(self, name, base):
        self.name = name
        self.base = base

    def salary(self):
        return self.base

class Manager(Employee):
    def __init__(self, name, base, bonus):
        super().__init__(name, base)
        self.bonus = bonus

    def salary(self):
        return self.base + self.bonus

n = int(input())
total = 0
for i in range(n):
    p = input().split()
    if p[0] == 'M':
        e = Manager(p[1], int(p[2]), int(p[3]))
    else:
        e = Employee(p[1], int(p[2]))
    print(e.name, e.salary())
    total += e.salary()
print('合计', total)

class Shape:
    def area(self):
        return 0

class Rect(Shape):
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h

class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def area(self):
        return 3.14 * self.r * self.r

n = int(input())
shapes = []
for i in range(n):
    p = input().split()
    if p[0] == 'R':
        shapes.append(Rect(float(p[1]), float(p[2])))
    else:
        shapes.append(Circle(float(p[1])))
total = 0
for s in shapes:
    print('{:.2f}'.format(s.area()))
    total += s.area()
print('总面积:{:.2f}'.format(total))
